/*
 * NOVODEX LOCAL MODIFICATION
 * upstream: External/opcode/upstream/Opcode/OPC_BaseModel.h
 *
 * [1] OPCODECREATE gains one pointer at +0x04, ahead of mSettings, so
 *     sizeof(OPCODECREATE) is 32 and mSettings.mLimit sits at +0x08.
 *     Non-null means Model::Build loads a serialized tree instead of building.
 *     established at 0x000e9122 `mov eax,[edi+4]; test eax,eax; jne` skips the mLimit check
 *     and CheckTopology; 0x000e9161 tests it again and dispatches the loader.
 *     0x000e92d2 defaults it to 0 in the constructor. 0x000522cf writes the
 *     caller's third stack argument here from InternalTriangleMesh.cpp.
 * [2] Three virtuals appended to BaseModel at slots 4, 5 and 6. GetUsedBytes is
 *     NOT displaced on this class -- it keeps slot 2. (The displacement is on
 *     AABBOptimizedTree; see OPC_OptimizedTree.h.)
 *     established at the Model vtable at .rdata:0x0011bac8 and the BaseModel vtable at
 *     .rdata:0x0011bb5c both have SEVEN slots where stock has four:
 *     [0x000e9280|0x000e95a0, Build, GetUsedBytes, 0x000e9410 Refit,
 *      0x000e9420, 0x000e9440, 0x000e94c0]. Slot 7 of 0x0011bac8 is already the
 *     "OPCODE WARNING: supports complete trees only!" literal at 0x0011bae4.
 *     BaseModel's slots 1 and 2 are _purecall (0x000f41dc), matching stock's
 *     pure Build and GetUsedBytes, which is what pins the slot numbering.
 *     Slot 5 is reached at 0x000e945f, slot 6 at 0x000e916d and 0x000e953d.
 *     Argument counts come from the returns: 0x000e9420 ends `ret` (no stack
 *     arguments), 0x000e9440 and 0x000e94c0 end `ret 4` (one).
 */
